# TartanIMU final training on Kaggle GPU: wide model + uniform per-trajectory sampling, train+val, EMA+SWA.
import base64, json, os, pathlib, subprocess, sys, time, shutil
W = pathlib.Path("/kaggle/working"); os.chdir(W)
for name, src in json.loads(base64.b64decode("")).items():
    (W / name).write_text(src)
cands = [pathlib.Path("/kaggle/input/competitions/tartan-imu-challenge-iros2026"), pathlib.Path("/kaggle/input/tartan-imu-challenge-iros2026")]
cands += [p.parent.parent for p in pathlib.Path("/kaggle/input").rglob("train_windows.csv")]
data = next(p for p in cands if (p / "index" / "train_windows.csv").exists())
print("data:", data, flush=True)
if not (W / "data").exists(): os.symlink(data, W / "data")
print(subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout, flush=True)
NAME = "final_kaggle_w_uni"; EPOCHS = int(os.environ.get("EPOCHS", "160"))
cmd = ["python", "train.py", "--name", NAME, "--splits", "train,val", "--epochs", str(EPOCHS), "--steps", "250", "--physics", "1", "--dilate", "1.3",
       "--rot-deg-drone", "45", "--boost-a", "1", "--traj-uniform", "1", "--swa-from", str(EPOCHS - 20), "--width", "192", "--ctx-layers", "3"]
t0 = time.time()
p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
for line in p.stdout:
    if line.startswith('{"epoch"'):
        r = json.loads(line)
        if r["epoch"] % 10 == 0 or r["epoch"] == EPOCHS: print({k: r[k] for k in ("epoch", "min", "l_win")}, flush=True)
    elif "Warning" not in line: print(line.rstrip(), flush=True)
p.wait(); assert p.returncode == 0, "training failed"
print(f"training done in {(time.time()-t0)/60:.1f} min", flush=True)
out = subprocess.run(["python", "predict.py", "--ckpt", f"runs/{NAME}/swa.pt", "--out", "submission.csv"], capture_output=True, text=True)
print("\n".join(l for l in (out.stdout + out.stderr).splitlines() if "Warning" not in l), flush=True)
shutil.copy(f"runs/{NAME}/swa.pt", W / f"{NAME}_swa.pt"); shutil.copy(f"runs/{NAME}/log.csv", W / "log.csv")
shutil.rmtree("runs"); os.unlink(W / "data")
for n in ["common.py", "kaggle_metric.py", "model.py", "train.py", "predict.py"]: (W / n).unlink()
print("outputs:", sorted(p.name for p in W.iterdir()))
